-- BHOP vehicle photos (137 vehicles). Run AFTER bhop_vehicles.sql. Only fills photo fields that are still empty.
UPDATE vehicles v SET
  photo_front = CASE WHEN COALESCE(v.photo_front,'')='' THEN 'https://lskouiyvdngdzaquurhk.supabase.co/storage/v1/object/public/cars_parts/vehicles/'||v.code||'/front.jpg' ELSE v.photo_front END,
  photo_rear  = CASE WHEN COALESCE(v.photo_rear,'')=''  AND v.code IN ('BU011A','BU012A','BU013A','BU014A','BU015A','CV420A','CV421A','CV422A','CV424A','CV425A','CV426A','CV427A','DW041A','HD068A','LX065A','LX066A','LX067A','LX068A','LX069A','LX070A','LX071A','LX072A','MZ085A','MZ092A','MZ093A','MZ094A','MZ095A','MZ096A','TS007A','TS008A','TS009A','TS010A','TS011A','TY155A','TY156A','TY157A','TY158A','TY159A','TY160A','TY161A','TY162A','TY163A','TY164A','TY165A','TY166A','TY168A','TY169A','TY170A','TY171A','TY172A','TY174A','TY177A','TY178A','TY179A','TY181A','TY182A','TY183A','TY184A','TY186A','TY187A','TY188A','TY189A','TY190A','TY191A','TY192A','TY193A','TY194A','TY195A','TY196A','TY197A','TY198A','TY199A','TY200A','TY201A','TY202A','TY203A','TY204A','TY205A','TY206A','TY207A','TY208A','TY210A','TY212A','TY213A','TY214A','TY216A','TY218A','TY219A') THEN 'https://lskouiyvdngdzaquurhk.supabase.co/storage/v1/object/public/cars_parts/vehicles/'||v.code||'/rear.jpg' ELSE v.photo_rear END
WHERE v.code IN ('BU005A','BU006A','BU007A','BU008A','BU009A','BU010A','BU011A','BU012A','BU013A','BU014A','BU015A','CV420A','CV421A','CV422A','CV423A','CV424A','CV425A','CV426A','CV427A','DW041A','DW042A','DW043A','HA001A','HA002A','HA003A','HA004A','HA005A','HA006A','HA008A','HA009A','HA012A','HA013A','HA014A','HA015A','HA016A','HD067A','HD068A','LX065A','LX066A','LX067A','LX068A','LX069A','LX070A','LX071A','LX072A','MZ074A','MZ075A','MZ076A','MZ077A','MZ078A','MZ079A','MZ080A','MZ081A','MZ082A','MZ083A','MZ085A','MZ086A','MZ087A','MZ089A','MZ090A','MZ091A','MZ092A','MZ093A','MZ094A','MZ095A','MZ096A','TS005A','TS006A','TS007A','TS008A','TS009A','TS010A','TS011A','TY155A','TY156A','TY157A','TY158A','TY159A','TY160A','TY161A','TY162A','TY163A','TY164A','TY165A','TY166A','TY168A','TY169A','TY170A','TY171A','TY172A','TY173A','TY174A','TY175A','TY176A','TY177A','TY178A','TY179A','TY180A','TY181A','TY182A','TY183A','TY184A','TY186A','TY187A','TY188A','TY189A','TY190A','TY191A','TY192A','TY193A','TY194A','TY195A','TY196A','TY197A','TY198A','TY199A','TY200A','TY201A','TY202A','TY203A','TY204A','TY205A','TY206A','TY207A','TY208A','TY209A','TY210A','TY211A','TY212A','TY213A','TY214A','TY215A','TY216A','TY217A','TY218A','TY219A','TY220A');

SELECT count(*) AS with_front FROM vehicles WHERE photo_front LIKE '%/cars_parts/vehicles/%';
